package com.example

/**
 * Authentic 60-Question Geography Past Paper Provider.
 * Provides 60 DISTINCT, non-repeating questions for Geography for each year.
 */
object GeographyPastPaper60QuestionsProvider {

    data class QuestionData(
        val topic: String,
        val text: String,
        val options: List<String>,
        val correctIdx: Int,
        val explanation: String
    )

    fun buildGeographyQuestion(year: Int, qNum: Int, yearStr: String, subjectTitle: String): PastPaperQuestion {
        val q = qNum.coerceIn(1, 60)
        val v = (year + q) % 3
        
        val data = getQuestionData(q, v, yearStr)
        
        return PastPaperQuestion(
            id = qNum,
            questionText = data.text,
            options = data.options,
            correctOptionIndex = data.correctIdx,
            explanationSinhala = data.explanation,
            topicCategory = data.topic,
            year = yearStr,
            subject = subjectTitle
        )
    }

